<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;
final class StaffPosView
{
    private static function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
    private static function money(int $v):string{return 'INR '.number_format($v/100,2,'.','');}
    private static function form(array $s,string $csrf,string $op,array $fields=[]):string{$x='<form method="post" data-pos-form>';foreach(['_csrf'=>$csrf,'action'=>'pos-'.$op,'merchant'=>$s['merchant'],'outlet'=>$s['outlet'],'request'=>bin2hex(random_bytes(16))]+$fields as $n=>$v)$x.='<input type="hidden" name="'.$n.'" value="'.self::h($v).'">';return $x;}
    private static function page(array $s,string $title,string $body):string{return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$title.' · KIOS</title><link rel="stylesheet" href="/assets/merchant-setup.css"><link rel="stylesheet" href="/assets/staff-pos.css"><script src="/assets/staff-pos.js" defer></script></head><body><main data-staff-pos data-merchant="'.self::h($s['merchant']).'" data-outlet="'.self::h($s['outlet']).'"><header><p class="eyebrow">Restricted synthetic demonstration · Internal service</p><h1>'.$title.'</h1><p>No payment is due. Customer ordering, payments and physical printing remain disabled.</p></header>'.$body.'</main></body></html>';}
    public static function render(array $s,string $csrf,string $selected='',string $message='',bool $error=false):string{
        $h=static fn($v)=>self::h($v);$url='/merchant.php?pos=1&amp;merchant='.$h($s['merchant']).'&amp;outlet='.$h($s['outlet']);$draft=null;if($selected!==''){foreach($s['sessions']as $v)if($v['service_id']===$selected)$draft=$v;if($draft===null)throw new \DomainException('Service outside loaded outlet history.');}
        $body='<nav class="pos-nav" aria-label="Staff service"><a href="'.$url.'">New service</a><a href="#service-history">Service progress</a>'.($s['canPrepare']?'<a href="/merchant.php?service-kitchen=1&amp;merchant='.$h($s['merchant']).'&amp;outlet='.$h($s['outlet']).'">Kitchen workspace</a>':'').'<a href="'.$url.'">Refresh</a></nav>';
        if($message!=='')$body.='<p class="message'.($error?' error':'').'" role="'.($error?'alert':'status').'">'.$h($message).'</p>';
        if($draft===null||$draft['status']==='DRAFT'){
            $body.='<section class="panel"><h2>1 · Choose occupied table</h2><label>Floor<select data-pos-floor><option value="">All floors</option>';foreach($s['floors']as $f)$body.='<option value="'.$h($f['floor_id']).'">'.$h($f['name']).'</option>';$body.='</select></label><div class="pos-tables">';foreach($s['tables']as $t){$allowed=$t['active']&&$t['operational_state']==='OCCUPIED'&&(int)$t['operational_until']>time();$body.='<button type="button" data-pos-table="'.$h($t['table_id']).'" data-floor="'.$h($t['floor_id']).'" aria-pressed="'.(($draft['table_id']??'')===$t['table_id']?'true':'false').'"'.(!$allowed?' disabled':'').'><strong>'.$h($t['name']).'</strong><span>'.$t['capacity'].' seats · '.$h(str_replace('_',' ',$t['operational_state'])).'</span></button>';}$body.='</div><p>Seat a synthetic party in Floor Manager first. A table can have one active service at a time.</p></section><div class="pos-layout"><section class="panel"><h2>2 · Choose products</h2><div class="pos-filters"><label>Search products<input type="search" data-pos-search></label><label>Category<select data-pos-category><option value="">All categories</option>';$categories=[];foreach($s['products']as $p)$categories[$p['category_id']]=$p['category_name'];foreach($categories as $id=>$name)$body.='<option value="'.$id.'">'.$h($name).'</option>';$body.='</select></label></div><div class="pos-products">';$groups=[];foreach($s['products']as $p)$groups[$p['product_id']][]=$p;
            foreach($groups as $id=>$variants){$p=$variants[0];$body.='<article data-pos-product="'.$id.'" data-category="'.$p['category_id'].'"><div class="pos-placeholder" role="img" aria-label="No product photograph">No photograph</div><h3>'.$h($p['name']).'</h3><p>'.$h($p['category_name']).'</p><label>Serving<select data-pos-variant>';foreach($variants as $v)if($v['variant_active'])$body.='<option value="'.$v['variant_id'].'" data-price="'.$v['price_paise'].'">'.$h($v['label']).' · '.self::money((int)$v['price_paise']).'</option>';$body.='</select></label><label>Quantity<input data-pos-quantity type="number" min="1" max="99" value="1"></label><button type="button" data-pos-add'.(!$p['available']||!$p['active']?' disabled':'').'>'.($p['available']&&$p['active']?'Add to draft':'Unavailable').'</button></article>';}
            $body.='</div></section><aside class="panel pos-draft"><h2>3 · Review draft</h2><p data-pos-table-label>Choose an occupied table.</p><div data-pos-cart role="region" aria-label="Draft items"></div><p data-pos-estimate role="status"></p>'.self::form($s,$csrf,'save',['service'=>$draft['service_id']??'','version'=>$draft['version']??'0','table'=>$draft['table_id']??'','lines_json'=>'[]']).'<button>Save draft & review</button></form><p>Unsaved edits stay in this browser until Save. Saving validates current products and prices on the server.</p><div data-pos-initial hidden data-lines="'.$h(json_encode($draft['draft']['input']??[],JSON_THROW_ON_ERROR)).'"></div>';
            if($draft){$body.='<section class="pos-saved"><h3>Saved review</h3>';foreach($draft['draft']['quote']['display']as $line)$body.='<p>'.$h($line['name'].' · '.$line['serving']).' × '.$line['quantity'].' — '.self::money($line['lineTotalPaise']).'</p>';$body.='<strong>Operational value '.self::money($draft['draft']['quote']['totalPaise']).'</strong><p>No payment is due. Submit uses this saved review, not unsaved edits.</p>'.self::form($s,$csrf,'submit',['service'=>$draft['service_id'],'version'=>$draft['version']]).'<button data-pos-submit>Submit saved draft to kitchen</button></form>'.self::form($s,$csrf,'cancel',['service'=>$draft['service_id'],'version'=>$draft['version']]).'<button class="pos-secondary">Cancel draft</button></form></section>';}$body.='</aside></div>';
        }
        $tableNames=array_column($s['tables'],'name','table_id');$body.='<section class="panel" id="service-history"><h2>Service progress</h2><p>Latest 200 services. READY means kitchen preparation finished; SERVED is an explicit service action. Neither releases seating.</p><div class="pos-services">';
        foreach($s['sessions']as $v){$body.='<article data-service="'.$h($v['service_id']).'"><div class="pos-service-heading"><h3>'.$h($tableNames[$v['table_id']]??'Retained table').'</h3><strong>'.$h($v['status']==='SUBMITTED'?strtoupper($v['kitchen_status']):$v['status']).'</strong></div><p class="pos-nonfinancial">INTERNAL SERVICE · No payment due</p>';foreach($v['draft']['quote']['display']as $line)$body.='<p>'.$h($line['name'].' · '.$line['serving']).' × '.$line['quantity'].'</p>';
            if($v['status']==='DRAFT')$body.='<a href="'.$url.'&amp;service='.$h($v['service_id']).'">Open saved draft</a>';
            foreach($v['tasks']as $task)$body.='<details><summary>'.$h($task['station_name']).' · '.$h(strtoupper($task['status'])).' · Digital KOT</summary><pre>'.$h($task['payload_text']).'</pre></details>';
            if($v['status']==='SUBMITTED'&&$v['kitchen_status']==='ready')$body.=self::form($s,$csrf,'served',['service'=>$v['service_id'],'version'=>$v['version']]).'<button>Mark served · keep table occupied</button></form>';$body.='</article>';
        }$body.='</div></section>';return self::page($s,'Staff POS',$body);
    }
    public static function kitchen(array $s,string $csrf,string $message=''):string{
        $body='<nav class="pos-nav"><a href="?service-kitchen=1&amp;merchant='.self::h($s['merchant']).'&amp;outlet='.self::h($s['outlet']).'">Refresh kitchen</a></nav>';if($message!=='')$body.='<p role="status">'.self::h($message).'</p>';$body.='<section class="pos-services">';foreach($s['tasks']as $t){$body.='<article data-service-task="'.$t['preparation_task_id'].'"><h2>'.self::h($t['table_name']).'</h2><p>'.self::h($t['station_name']).' · <strong>'.self::h(strtoupper($t['status'])).'</strong></p><p>INTERNAL SERVICE · No payment due</p><pre>'.self::h($t['payload_text']).'</pre>';if(in_array($t['status'],['queued','preparing'],true))$body.=self::form($s,$csrf,'task',['task'=>$t['preparation_task_id'],'expected'=>$t['status']]).'<button>'.($t['status']==='queued'?'Start preparing':'Mark READY').'</button></form>';$body.='</article>';}$body.='</section>';if(!$s['tasks'])$body.='<p>No internal preparation tasks are visible for your authorized stations.</p>';return self::page($s,'Internal kitchen',$body);
    }
}
